  for(let i=0;i<LEAGUES.totalFighters;i++)newFighters.push(makeLeagueFighter());world=LEAGUES.create(input.worldId,newFighters.map(f=>f.character),crypto.getRandomValues(new Uint32Array(1))[0],settings);
